"use client";

import { useCallback, useEffect, useState } from "react";

type Submission = { id: string; status: string; content: unknown; submittedAt: string | null; feedback: string | null; score: number | null; assignment: { title: string; description: string | null; type: string; dueAt: string | null; maxScore: number; group: { name: string } | null; teacher: { name: string | null } } };

export default function StudentHomeworkPage() {
  const [items, setItems] = useState<Submission[]>([]); const [drafts, setDrafts] = useState<Record<string, string>>({}); const [error, setError] = useState(""); const [saving, setSaving] = useState<string | null>(null);
  const load = useCallback(async () => { const r = await fetch("/api/student/assignments", { cache: "no-store" }); const p = await r.json().catch(() => null); if (r.ok) setItems(p.data ?? []); else setError(p?.error ?? "Unable to load homework."); }, []);
  useEffect(() => { void load(); }, [load]);
  const submit = async (id: string) => { setSaving(id); setError(""); let content: unknown = { text: drafts[id] ?? "" }; try { content = JSON.parse(drafts[id] ?? ""); } catch { /* Plain text is valid assignment content. */ } const r = await fetch(`/api/student/assignments/${id}/submit`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content }) }); const p = await r.json().catch(() => null); setSaving(null); if (!r.ok) { setError(p?.error ?? "Unable to submit homework."); return; } void load(); };
  return <section className="space-y-6"><header><h2 className="text-3xl font-bold">Homework</h2><p className="mt-2 text-slate-600">Complete assignments from your teacher and track feedback here.</p></header>{error ? <p className="rounded-lg bg-red-50 p-3 text-red-800">{error}</p> : null}{items.length === 0 ? <div className="rounded-2xl border border-dashed bg-white p-8 text-slate-600">You have no active assignments.</div> : <div className="space-y-4">{items.map((item) => <article key={item.id} className="rounded-2xl border bg-white p-5"><div className="flex flex-wrap justify-between gap-3"><div><h3 className="text-xl font-bold">{item.assignment.title}</h3><p className="mt-1 text-sm text-slate-600">{item.assignment.group?.name ?? item.assignment.teacher.name ?? "Teacher"} · {item.assignment.type}</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{item.status.replace(/_/g, " ")}</span></div>{item.assignment.description ? <p className="mt-3 text-slate-700">{item.assignment.description}</p> : null}<p className="mt-3 text-sm text-slate-600">Due: {item.assignment.dueAt ? new Date(item.assignment.dueAt).toLocaleString() : "No deadline"} · Max score: {item.assignment.maxScore}</p>{item.feedback ? <div className="mt-4 rounded-lg bg-blue-50 p-3"><b>Teacher feedback:</b> {item.feedback}{item.score != null ? ` (${item.score}/${item.assignment.maxScore})` : ""}</div> : null}{item.status !== "GRADED" ? <div className="mt-4"><label className="block text-sm font-semibold" htmlFor={`homework-${item.id}`}>Your answer</label><textarea id={`homework-${item.id}`} value={drafts[item.id] ?? (typeof item.content === "object" && item.content && "text" in item.content ? String((item.content as { text?: unknown }).text ?? "") : "")} onChange={(event) => setDrafts((prev) => ({ ...prev, [item.id]: event.target.value }))} rows={4} className="mt-1 w-full rounded-lg border p-3" placeholder="Write your answer or paste JSON content."/><button type="button" disabled={saving === item.id} onClick={() => void submit(item.id)} className="mt-3 rounded-lg bg-blue-700 px-4 py-2 font-semibold text-white disabled:opacity-50">{saving === item.id ? "Submitting…" : "Submit work"}</button></div> : null}</article>)}</div>}</section>;
}
